const raw = $input.first().json;
const payload = raw.body || raw;

// Structured CTWA Welcome Flow Options
const ctwaWelcomePayload = {
  welcome_message: "Welcome to Ko Lake Villa! 🌊 Thank you for inquiring via our Reverse Auction. Please choose an option below:",
  quick_options: [
    { id: 1, title: "Entire Villa Buyout", desc: "7 En-Suite Bedrooms (up to 24 guests, from $250/night)" },
    { id: 2, title: "Last-Minute Room", desc: "AC En-Suite Bedroom by the lake (from $45/night)" },
    { id: 3, title: "Direct Reverse Auction Bid", desc: "Name your travel dates and proposed rate" }
  ],
  canonical_website: "https://www.kolakevilla.com",
  prefilled_deep_link: "https://wa.me/94711730345?text=" + encodeURIComponent("Hi Ko Lake Villa! I saw your reverse auction offer. I'd like to check rates for [Dates] for [X] guests."),
  official_cta: "For more information about our unique accommodations and to explore the amenities of Ko Lake Villa, please visit our website at www.kolakevilla.com. Book your stay today and experience the tranquility of lakeside living!"
};

return [{
  json: {
    status: 'RECEIVED_AND_PROCESSED',
    event: payload.event || 'DEPLOY_REVERSE_AUCTION',
    campaign: payload.campaign_slug || 'ko-lake-reverse-auction',
    whatsapp_recipient: '+94 71 173 0345',
    pricing: {
      starting_bid_usd: payload.pricing?.starting_bid || 420,
      whole_villa_floor_usd: 250,
      same_day_emergency_floor_usd: 180,
      single_room_floor_usd: 45
    },
    ctwa_conversion_flow: ctwaWelcomePayload,
    meta_status: payload.meta_ads?.status || 'ACTIVE',
    meta_campaign_id: '120248229307270630',
    dispatched_at: new Date().toISOString()
  }
}];
